export function tokenLogo(asset: { chainId: number; kind: string; contractAddress?: string | null }): string | undefined {
  if (asset.kind === 'native') return 'https://raw.githubusercontent.com/trustwallet/assets/master/blockchains/ethereum/info/logo.png';
  return logos[asset.chainId + ':' + asset.contractAddress?.toLowerCase()];
}
